import {JOBS} from './engine.js';
import {ensureCommand,GUARD_POSTS} from './farm-command.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function commandHtml(game){ensureCommand(game.s);const s=game.s;
 return `<section class="farm-command"><p class="eyebrow">FARM COMMAND</p><h3>People, projects & perimeter</h3><p>Rank jobs for automatic assignment. Direct orders and away teams take precedence. Your farm is paused while this panel is open.</p><div class="command-policies">${[['emergencies','Emergency assignments','Prioritize eligible defenders at night and builders when the farmhouse is critical.'],['repairsFirst','Repairs before construction','Repair the farmhouse first, then safe damaged defenses.'],['queue','Ordered construction','Within each priority tier, follow the displayed queue instead of choosing the nearest site.']].map(([k,name,detail])=>`<label><input type="checkbox" data-command-policy="${k}" ${s.command[k]?'checked':''}><strong>${name}</strong><small>${detail}</small></label>`).join('')}</div><h3>Survivor priorities</h3><p>First job with available work wins. No work means rest. Turning automatic work off restores the original job when the survivor has no direct order.</p><div class="command-people">${s.people.map(p=>`<article><header><strong>${esc(p.name)}</strong><label><input type="checkbox" data-work-enable="${p.id}" ${p.workPlan.enabled?'checked':''}> Automatic</label></header><p>${esc(p.status)} · ${esc(game.workExplanation(p))}</p><div class="command-ranks">${[0,1,2].map(i=>`<label>Priority ${i+1}<select data-work-rank="${p.id}" data-rank="${i}" aria-label="${esc(p.name)} priority ${i+1}"><option value="">None</option>${Object.entries(JOBS).map(([k,v])=>`<option value="${k}" ${p.workPlan.jobs[i]===k?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`).join('')}<label>Guard post<select data-guard-post="${p.id}" aria-label="${esc(p.name)} guard post">${Object.entries(GUARD_POSTS).map(([k,v])=>`<option value="${k}" ${p.guardPost===k?'selected':''}>${v.name}</option>`).join('')}</select></label></div><small>Guard posts apply while defending, after equipment is collected.</small></article>`).join('')}</div><h3>Construction queue</h3><p>Materials are committed when ordered. Remaining value is the cancellation refund, not a second payment. House projects retain their separate work queue.</p><div class="command-projects">${game.constructionReport().map((r,i)=>`<article><strong>${i+1}. ${esc(r.name)}</strong><progress max="1" value="${r.progress}" aria-label="${esc(r.name)} completion"></progress><span>${Math.round(r.progress*100)}% · ${r.paid} scrap committed · ${r.remaining} refundable</span><small>${esc(r.reason)}</small><div><button type="button" data-queue-up="${r.id}" ${i===0?'disabled':''}>Move up</button><button type="button" data-queue-down="${r.id}" ${i===s.sites.length-1?'disabled':''}>Move down</button></div></article>`).join('')||'<p>No projects queued. Order projects in Build.</p>'}</div><h3>Night readiness</h3><p>${esc(game.nightBrief())}</p><div class="command-readiness">${game.commandReadiness().map(r=>`<div class="${r.ok?'ready':'check'}"><span>${r.ok?'READY':'CHECK'} · ${r.label}</span><strong>${r.value}</strong></div>`).join('')}</div><button type="button" class="primary-button" data-command-fallback="true">${s.command.fallback?'Release fallback — resume guard posts':'Fall back — rally defenders at farmhouse'}</button><p>Fallback remains active until released. Direct player orders still take precedence. Boundary breaches produce alerts as new gaps appear.</p></section>`;
}
export function commandClick(game,b){if(b.hasAttribute('data-command-fallback')){game.s.command.fallback=!game.s.command.fallback;return true;}for(const [key,delta] of [['queueUp',-1],['queueDown',1]])if(b.dataset[key]){game.moveConstruction(Number(b.dataset[key]),delta);return true;}return false;}
export function commandChange(game,e){const el=e.target;ensureCommand(game.s);if(el.dataset.commandPolicy){game.s.command[el.dataset.commandPolicy]=el.checked;return true;}if(el.dataset.guardPost){game.setGuardPost(Number(el.dataset.guardPost),el.value);return true;}const id=Number(el.dataset.workEnable||el.dataset.workRank),p=game.s.people.find(p=>p.id===id);if(!p)return false;if(el.dataset.workEnable){game.setWorkPlan(id,p.workPlan.jobs,el.checked);return true;}if(el.dataset.workRank){const jobs=[...p.workPlan.jobs];jobs[Number(el.dataset.rank)]=el.value;game.setWorkPlan(id,[...new Set(jobs.filter(Boolean))].length?[...new Set(jobs.filter(Boolean))]:['rest'],p.workPlan.enabled);return true;}return false;}
